def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = []
    for start, end in sorted_intervals:
        if not merged or merged[-1][1] < start:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

import heapq


def toposort(nodes, edges):
    # Deduplicate edges so they don't artificially inflate in-degrees
    unique_edges = set(edges)

    # Build in-degree and adjacency structures without mutating inputs
    indeg = {n: 0 for n in nodes}
    adj = {n: [] for n in nodes}

    for src, dst in unique_edges:
        adj[src].append(dst)
        indeg[dst] += 1

    # Min-heap to always pick the lexicographically smallest available node
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for neighbor in adj[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    if not items:
        return []
    batches = []
    current_names = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            batches.append(current_names)
            current_names = [name]
            current_weight = weight
        else:
            current_names.append(name)
            current_weight += weight
    if current_names:
        batches.append(current_names)
    return batches

import re

def parse_env(text):
    env = {}
    key_pat = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid environment line: {line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_pat.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and ((value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'")):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    data_bytes = b''.join(chunks)
    text = data_bytes.decode('utf-8')
    text = text.replace('\r\n', '\n').replace('\r', '\n')

    lines = text.split('\n')

    events = []
    current_data = []
    done = False

    for line in lines:
        if done:
            break

        if line == '':
            if current_data:
                event_text = '\n'.join(current_data)
                if event_text == '[DONE]':
                    done = True
                else:
                    events.append(event_text)
                current_data = []
            continue

        if line.lstrip().startswith(':'):
            continue

        if ':' not in line:
            continue

        field, _, value = line.partition(':')
        field = field.strip()
        if value.startswith(' '):
            value = value[1:]

        if field == 'data':
            current_data.append(value)

    return events

import math

def retry_delay(attempt: int, base: float, cap: float) -> float:
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    if base >= cap:
        return float(cap)
    # 0 < base < cap
    # We need to check if base * 2**attempt >= cap
    # equivalent to attempt >= log2(cap / base)
    try:
        threshold = math.log2(cap / base)
    except ValueError:
        # cap / base could be negative if signs were weird, but we already checked nonnegative
        return float(cap)
    if attempt >= threshold:
        return float(cap)
    # attempt < threshold  =>  base * 2**attempt < cap
    # at this point attempt is small enough that 2**attempt is safe to compute
    # (if attempt were 10**9, threshold would be <= 10**9 only if cap/base >= 2**10**9,
    #  which would make the product huge; but the problem asks to avoid constructing
    #  such integers. In the uncapped branch, attempt is implicitly bounded by log2(cap/base),
    #  and we can safely use Python's integer power then convert to float.)
    return float(base * (2 ** attempt))

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError("Queued reservation exceeds budget")

    current_slots = len(active)
    current_tokens = sum(active)
    admitted = []
    i = 0

    while i < len(queued):
        r = queued[i]
        if current_slots + 1 <= slots and current_tokens + r <= budget:
            admitted.append(r)
            current_slots += 1
            current_tokens += r
            i += 1
        else:
            break

    remaining = queued[i:]
    return (admitted, remaining)
